Choose a clinic, a service and a time","Confirm and get a reminder","The front desk''s day across both clinics"],"responsive_notes":"Patients book on phones; the front desk works on a desktop schedule that also reads on a tablet.","brand_context":"No brand material is mentioned; neutral placeholders until the practice shares its logo and colours."},"screens":[{"id":"s1","template":"booking_form","title":"Book a visit","purpose":"A patient chooses the clinic, the service and a time.","headline":"Book your dental visit","items":[{"title":"Clinic","text":"Choose the clinic nearest to you"},{"title":"Service","text":"Check-up, cleaning or treatment"},{"title":"Time","text":"Open times only"}],"primary_action":"Continue"},{"id":"s2","template":"confirmation","title":"Confirm","purpose":"The patient confirms and chooses a reminder.","headline":"Book this visit?","supporting_text":"You can change or cancel it later.","items":[{"title":"Clinic","text":"The clinic you chose"},{"title":"Reminder","text":"A message the day before"}],"primary_action":"Confirm booking","secondary_action":"Change time"},{"id":"s3","template":"schedule_calendar","title":"Today''s schedule","purpose":"The front desk sees both clinics'' day.","headline":"Today across both clinics","items":[{"title":"Morning","text":"Booked and open times"},{"title":"Missed","text":"Patients who did not arrive"}],"primary_action":"Add a booking"}],"user_flow":[{"step":"The patient picks a clinic, a service and a time.","screen":"s1"},{"step":"Confirms the visit and chooses a reminder.","screen":"s2"},{"step":"The front desk sees the booking on the day''s schedule.","screen":"s3"}]}'::jsonb, 'manual', 'omar@review-seed.invalid');
