-- Prospect 2. Outbound prospect, contacted, with a touch and a dated next action
do $$
declare
  v uuid;
begin
  v := public.crm_save_prospect(null, '{"company_name":"Saffron Kitchen Group","country":"United Arab Emirates","sector":"Restaurants","pool":"trigger_startup","lead_origin":"outbound","contact_name":"Rami Khoury","contact_role":"Operations lead","contact_channel":"linkedin","language":"en","trigger_note":"Hiring for online orders","owner":"omar"}'::jsonb, 'omar@review-seed.invalid');
